1	package meter
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“提前登记未来才开通的订阅后、等待期内的用量上报”提供回归保障。
10	// 能否接收一条事件，既要看事件是否已经发生（不晚于当前时刻），也要看事件发生
11	// 时刻是否属于某段实际订阅期间（开通计入、终止不计入）；账户保存了一份尚未生效
12	// 的订阅不构成接收资格。等待期内的任何拒绝都不得占用事件标识、不得累计数量、
13	// 不得提前激活订阅。
14	
15	// TestFutureEventDuringWaitingRejectedThenAcceptedAtActivation 覆盖题述主线：
16	// 一月十日登记一月二十日十二点开通的订阅；等待期内提前上报发生于开通瞬间、
17	// 数量为三的事件返回 ErrEventInFuture；当前时刻恰好到达开通瞬间后，以原事件
18	// 标识、原发生时刻、原数量再次提交，作为首次接收成功并归入一月账期；原样重报
19	// 仍成功但不再次接收。等待期的拒绝不能占用事件标识，否则合法提交会被误当成重报。
20	func TestFutureEventDuringWaitingRejectedThenAcceptedAtActivation(t *testing.T) {
21		s, clk := newTestService(utc(2026, 1, 10, 12, 0))
22		mustPlan(t, s, planDef("a", 1000, 10, 100, 500))
23		mustAccount(t, s, "u")
24		activateAt := utc(2026, 1, 20, 12, 0)
25		mustSubscribe(t, s, "u", "a", activateAt)
26	
27		ev := Event{AccountID: "u", EventID: "evt-at-activation", At: activateAt, Quantity: 3}
28	
29		// 登记当天提前上报“发生于开通瞬间”的事件：此刻事件仍晚于当前时刻，
30		// 必须按 ErrEventInFuture 拒绝，不能因为账户已保存订阅就接收。
31		if _, err := s.RecordEvent(ev); !errors.Is(err, ErrEventInFuture) {
32			t.Fatalf("early report at activation instant = %v, want ErrEventInFuture", err)
33		}
34		// 拒绝不累计数量：一月没有任何用量。
35		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 0 {
36			t.Fatalf("jan usage after rejected future event = %d, want 0", u.Total)
37		}
38		// 拒绝也不提前激活订阅：状态仍显示未生效且无任何用量记录。
39		st, _ := s.Status("u")
40		assertNotSubscribed(t, st)
41		if len(st.MonthlyUsage) != 0 {
42			t.Fatalf("monthly usage while waiting = %+v, want empty", st.MonthlyUsage)
43		}
44	
45		// 开通前一分钟提交同一条“发生于开通瞬间”的事件：仍晚于当前时刻，依旧拒绝。
46		clk.t = activateAt.Add(-time.Minute)
47		if _, err := s.RecordEvent(ev); !errors.Is(err, ErrEventInFuture) {
48			t.Fatalf("report one minute before activation = %v, want ErrEventInFuture", err)
49		}
50		st, _ = s.Status("u")
51		assertNotSubscribed(t, st)
52		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 0 {
53			t.Fatalf("jan usage after second rejection = %d, want 0", u.Total)
54		}
55	
56		// 当前时刻恰好到达开通瞬间：以原标识、原时刻、原数量提交，首次接收成功，
57		// 归入一月（UTC 自然月）账期。等待期的拒绝没有占用该事件标识。
58		clk.t = activateAt
59		r, err := s.RecordEvent(ev)
60		if err != nil || !r.Accepted || r.Period != jan(2026) {
61			t.Fatalf("first acceptance at activation instant: %+v %v", r, err)
62		}
63		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 3 {
64			t.Fatalf("jan usage after acceptance = %d, want 3", u.Total)
65		}
66		// 订阅此刻才生效，用量同时体现在账户查询中。
67		st, _ = s.Status("u")
68		if !st.Subscribed {
69			t.Fatalf("Subscribed = false at activation instant: %+v", st)
70		}
71		if st.CurrentTerms.PlanID != "a" {
72			t.Fatalf("CurrentTerms = %+v, want plan a snapshot", st.CurrentTerms)
73		}
74		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 3}) {
75			t.Fatalf("monthly usage at activation = %+v, want [2026-01 = 3]", st.MonthlyUsage)
76		}
77	
78		// 此后原样重报仍成功，但表示没有再次接收：返回一月账期，数量保持为三。
79		r2, err := s.RecordEvent(ev)
80		if err != nil || r2.Accepted || r2.Period != jan(2026) {
81			t.Fatalf("identical replay after activation: %+v %v", r2, err)
82		}
83		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 3 {
84			t.Fatalf("jan usage after replay = %d, want 3", u.Total)
85		}
86		st, _ = s.Status("u")
87		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0].Total != 3 {
88			t.Fatalf("monthly usage after replay = %+v, want unchanged [2026-01 = 3]", st.MonthlyUsage)
89		}
90	}
91	
92	// TestPastEventBeforeActivationRejectedWithinSameMonth 锁定“事件已经发生却早于
93	// 订阅开通”的情形：开通之后补报当天 11:59 的事件必须返回
94	// ErrEventBeforeSubscription，不能因属于同一个 UTC 自然月而接收；开通时刻本身
95	// 包含在订阅期间内。被拒事件同样不占用标识、不累计数量。
96	func TestPastEventBeforeActivationRejectedWithinSameMonth(t *testing.T) {
97		s, clk := newTestService(utc(2026, 1, 10, 12, 0))
98		mustPlan(t, s, planDef("a", 0, 100, 0, 0))
99		mustAccount(t, s, "u")
100		activateAt := utc(2026, 1, 20, 12, 0)
101		mustSubscribe(t, s, "u", "a", activateAt)
102	
103		// 开通之后一分钟，补报当天 11:59 的事件：事件已经发生，但早于开通时刻。
104		clk.t = activateAt.Add(time.Minute)
105		before := Event{AccountID: "u", EventID: "late-before-open", At: utc(2026, 1, 20, 11, 59), Quantity: 2}
106		if _, err := s.RecordEvent(before); !errors.Is(err, ErrEventBeforeSubscription) {
107			t.Fatalf("backfill before activation = %v, want ErrEventBeforeSubscription", err)
108		}
109		// 开通前一纳秒同样不属于订阅期间。
110		nanosBefore := Event{AccountID: "u", EventID: "ns-before-open", At: activateAt.Add(-time.Nanosecond), Quantity: 1}
111		if _, err := s.RecordEvent(nanosBefore); !errors.Is(err, ErrEventBeforeSubscription) {
112			t.Fatalf("one nanosecond before activation = %v, want ErrEventBeforeSubscription", err)
113		}
114		// 不能因为与开通时刻同属一个自然月就接收：一月累计仍为零。
115		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 0 {
116			t.Fatalf("jan usage after before-activation rejections = %d, want 0", u.Total)
117		}
118	
119		// 开通时刻本身包含在订阅期间内：同分钟、同月份的合法事件接收成功。
120		atExact := Event{AccountID: "u", EventID: "at-open", At: activateAt, Quantity: 5}
121		r, err := s.RecordEvent(atExact)
122		if err != nil || !r.Accepted || r.Period != jan(2026) {
123			t.Fatalf("event exactly at activation: %+v %v", r, err)
124		}
125		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 5 {
126			t.Fatalf("jan usage = %d, want 5", u.Total)
127		}
128	
129		// 被拒事件不占用标识：同一标识改报订阅期间内、且已经发生的合法时刻与数量，
130		// 必须按全新事件接收，而不是 ErrEventConflict（若拒绝时落库则会冲突）。
131		// 当前时刻为开通后一分钟，开通瞬间已是过去。
132		reuse := Event{AccountID: "u", EventID: "late-before-open", At: activateAt, Quantity: 4}
133		r2, err := s.RecordEvent(reuse)
134		if err != nil || !r2.Accepted || r2.Period != jan(2026) {
135			t.Fatalf("reuse rejected event id for valid event: %+v %v", r2, err)
136		}
137		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 9 {
138			t.Fatalf("jan usage after id reuse = %d, want 9", u.Total)
139		}
140	}
141	
142	// TestFutureActivationEventJudgedByInstantAcrossZones 验证时区不影响判定：
143	// 开通时刻、事件发生时刻与当前时刻分别用不同时区表示时，服务一律按实际瞬间
144	// 比较——等待期拒绝、开通瞬间接收、归入的 UTC 自然月均与全 UTC 表示一致。
145	func TestFutureActivationEventJudgedByInstantAcrossZones(t *testing.T) {
146		plus1 := time.FixedZone("UTC+1", 60*60)
147		activateUTC := utc(2026, 1, 20, 12, 0)
148	
149		s, clk := newTestService(utc(2026, 1, 10, 12, 0))
150		mustPlan(t, s, planDef("a", 1000, 10, 100, 0))
151		mustAccount(t, s, "z")
152		// 开通时刻用 +08:00 表示：本地 1 月 20 日 20:00 即 UTC 12:00。
153		mustSubscribe(t, s, "z", "a", time.Date(2026, 1, 20, 20, 0, 0, 0, zonePlus8))
154	
155		// 事件时刻同样用 +08:00 表示开通瞬间：登记当天（UTC 1 月 10 日）提前上报，
156		// 按实际瞬间判定仍是未来事件。
157		ev := Event{
158			AccountID: "z", EventID: "zoned-activation-event",
159			At:       time.Date(2026, 1, 20, 20, 0, 0, 0, zonePlus8),
160			Quantity: 3,
161		}
162		if !ev.At.Equal(activateUTC) {
163			t.Fatalf("test setup: event instant %v != %v", ev.At.UTC(), activateUTC)
164		}
165		if _, err := s.RecordEvent(ev); !errors.Is(err, ErrEventInFuture) {
166			t.Fatalf("zoned future event = %v, want ErrEventInFuture", err)
167		}
168	
169		// 当前时刻改用 -05:00 表示：本地 07:00 == UTC 12:00，恰好到达开通瞬间。
170		clk.t = time.Date(2026, 1, 20, 7, 0, 0, 0, zoneMinus5)
171		// 事件时刻改用 +01:00 表示：本地 13:00 == UTC 12:00，与登记的开通时刻
172		// 是同一瞬间，首次接收成功，归入一月 UTC 账期。
173		evPlus1 := Event{
174			AccountID: "z", EventID: "zoned-activation-event",
175			At:       time.Date(2026, 1, 20, 13, 0, 0, 0, plus1),
176			Quantity: 3,
177		}
178		if !evPlus1.At.Equal(activateUTC) {
179			t.Fatalf("test setup: +01:00 event instant %v != %v", evPlus1.At.UTC(), activateUTC)
180		}
181		r, err := s.RecordEvent(evPlus1)
182		if err != nil || !r.Accepted || r.Period != jan(2026) {
183			t.Fatalf("zoned event at zoned activation instant: %+v %v", r, err)
184		}
185	
186		// 开通前一分钟（本地 19:59 +08 == 11:59 UTC）的事件已经发生却早于订阅：
187		// 即使与开通时刻同属一个自然月也拒绝。
188		before := Event{
189			AccountID: "z", EventID: "zoned-before",
190			At:       time.Date(2026, 1, 20, 19, 59, 0, 0, zonePlus8),
191			Quantity: 1,
192		}
193		if _, err := s.RecordEvent(before); !errors.Is(err, ErrEventBeforeSubscription) {
194			t.Fatalf("zoned event before activation = %v, want ErrEventBeforeSubscription", err)
195		}
196	
197		// 用纯 UTC 表示原样重报开通瞬间事件：同一实际瞬间，成功但不再次接收，
198		// 账期仍为一月；一月累计始终为三。
199		if r, err := s.RecordEvent(Event{
200			AccountID: "z", EventID: "zoned-activation-event",
201			At: activateUTC, Quantity: 3,
202		}); err != nil || r.Accepted || r.Period != jan(2026) {
203			t.Fatalf("utc replay of zoned activation event: %+v %v", r, err)
204		}
205		if u, _ := s.MonthlyUsage("z", jan(2026)); u.Total != 3 {
206			t.Fatalf("jan usage across zones = %d, want 3", u.Total)
207		}
208		st, _ := s.Status("z")
209		if !st.Subscribed || st.CurrentTerms.PlanID != "a" {
210			t.Fatalf("status across zones = %+v, want subscribed plan a", st)
211		}
212		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 3}) {
213			t.Fatalf("monthly usage across zones = %+v, want [2026-01 = 3]", st.MonthlyUsage)
214		}
215	}
216	
217	// TestUsageBackfillDuringFutureResubscribeGap 覆盖重新开通等待期的同一规则：
218	// 旧订阅已于二月一日终止，账户提前登记二月十日十二点重新开通，二月五日仍处于
219	// 空档。账户未欠费、旧一月尚未出账时，补报旧订阅期间真实发生的用量成功，只
220	// 增加一月累计量，账户仍显示新订阅未生效；空档事件与指向未来开通瞬间的事件
221	// 都不能借未来登记获得接收资格。
222	func TestUsageBackfillDuringFutureResubscribeGap(t *testing.T) {
223		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
224		mustPlan(t, s, planDef("a", 1000, 10, 100, 0))
225		mustPlan(t, s, planDef("c", 3000, 30, 300, 0))
226		mustAccount(t, s, "g")
227		mustSubscribe(t, s, "g", "a", utc(2026, 1, 1, 0, 0))
228		if _, err := s.RecordEvent(Event{AccountID: "g", EventID: "jan-old", At: utc(2026, 1, 10, 0, 0), Quantity: 2}); err != nil {
229			t.Fatal(err)
230		}
231		mustCancel(t, s, "g") // 旧订阅二月一日终止。
232	
233		// 二月二日旧订阅已终止：提前登记二月十日中午重新开通。
234		clk.t = utc(2026, 2, 2, 9, 0)
235		reopenAt := utc(2026, 2, 10, 12, 0)
236		mustSubscribe(t, s, "g", "c", reopenAt)
237	
238		// 二月五日处于两段订阅之间的空档：新订阅未生效，账户也没有欠费停用。
239		clk.t = utc(2026, 2, 5, 10, 0)
240		st, _ := s.Status("g")
241		assertNotSubscribed(t, st)
242		if st.Suspended {
243			t.Fatalf("account suspended during gap: %+v", st)
244		}
245		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 2}) {
246			t.Fatalf("gap usage before backfill = %+v, want [2026-01 = 2]", st.MonthlyUsage)
247		}
248	
249		// 旧一月尚未出账：补报旧订阅期间（一月二十日）真实发生的用量，接收成功，
250		// 归入一月账期，只增加一月累计量。
251		backfill := Event{AccountID: "g", EventID: "jan-backfill", At: utc(2026, 1, 20, 8, 0), Quantity: 4}
252		r, err := s.RecordEvent(backfill)
253		if err != nil || !r.Accepted || r.Period != jan(2026) {
254			t.Fatalf("backfill old subscription usage during gap: %+v %v", r, err)
255		}
256		if u, _ := s.MonthlyUsage("g", jan(2026)); u.Total != 6 {
257			t.Fatalf("jan usage after backfill = %d, want 6", u.Total)
258		}
259		if u, _ := s.MonthlyUsage("g", feb(2026)); u.Total != 0 {
260			t.Fatalf("feb usage after january backfill = %d, want 0", u.Total)
261		}
262		// 补报旧用量不改变等待状态：账户仍显示新订阅未生效，也没有被提前激活。
263		st, _ = s.Status("g")
264		assertNotSubscribed(t, st)
265		if st.Suspended {
266			t.Fatalf("account suspended after backfill: %+v", st)
267		}
268		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 6}) {
269			t.Fatalf("gap usage after backfill = %+v, want only [2026-01 = 6]", st.MonthlyUsage)
270		}
271	
272		// 发生在二月空档内（二月三日，相对当前已是过去）的事件：以“不属于订阅
273		// 期间”的既有错误拒绝，不能借未来登记获得接收资格。
274		gapPast := Event{AccountID: "g", EventID: "gap-past", At: utc(2026, 2, 3, 8, 0), Quantity: 1}
275		if _, err := s.RecordEvent(gapPast); !errors.Is(err, ErrEventBeforeSubscription) {
276			t.Fatalf("event in resubscribe gap = %v, want ErrEventBeforeSubscription", err)
277		}
278		// 指向未来重新开通瞬间的事件在此刻仍是未来事件，同样不得接收。
279		atReopen := Event{AccountID: "g", EventID: "gap-at-reopen", At: reopenAt, Quantity: 1}
280		if _, err := s.RecordEvent(atReopen); !errors.Is(err, ErrEventInFuture) {
281			t.Fatalf("event at future reopen instant during gap = %v, want ErrEventInFuture", err)
282		}
283		// 两次拒绝都不留下用量：二月仍无累计，一月保持 6。
284		if u, _ := s.MonthlyUsage("g", feb(2026)); u.Total != 0 {
285			t.Fatalf("feb usage after gap rejections = %d, want 0", u.Total)
286		}
287		if u, _ := s.MonthlyUsage("g", jan(2026)); u.Total != 6 {
288			t.Fatalf("jan usage changed after gap rejections = %d, want 6", u.Total)
289		}
290	
291		// 到达重新开通瞬间：新订阅生效，历史用量只含一月；拒绝未提前激活任何东西。
292		clk.t = reopenAt
293		st, _ = s.Status("g")
294		if !st.Subscribed {
295			t.Fatalf("not subscribed at reopen instant: %+v", st)
296		}
297		if st.CurrentTerms.PlanID != "c" || st.CurrentTerms.MonthlyFee != 3000 {
298			t.Fatalf("current terms at reopen = %+v, want plan c snapshot", st.CurrentTerms)
299		}
300		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: jan(2026), Total: 6}) {
301			t.Fatalf("usage at reopen instant = %+v, want only [2026-01 = 6]", st.MonthlyUsage)
302		}
303	
304		// 一月补报事件原样重报：成功但不再次接收，账期仍是旧订阅的一月。
305		if r, err := s.RecordEvent(backfill); err != nil || r.Accepted || r.Period != jan(2026) {
306			t.Fatalf("replay january backfill after reopen: %+v %v", r, err)
307		}
308		// 空档事件在重新开通后仍不属于任何订阅期间：依旧拒绝。
309		if _, err := s.RecordEvent(gapPast); !errors.Is(err, ErrEventBeforeSubscription) {
310			t.Fatalf("gap event rechecked after reopen = %v, want ErrEventBeforeSubscription", err)
311		}
312		// 等待期以 ErrEventInFuture 被拒的同一事件标识未被占用：此刻合法提交，
313		// 首次接收并归入二月账期。
314		r2, err := s.RecordEvent(atReopen)
315		if err != nil || !r2.Accepted || r2.Period != feb(2026) {
316			t.Fatalf("rejected future-gap event accepted at reopen: %+v %v", r2, err)
317		}
318		if u, _ := s.MonthlyUsage("g", feb(2026)); u.Total != 1 {
319			t.Fatalf("feb usage at reopen instant = %d, want 1", u.Total)
320		}
321		if u, _ := s.MonthlyUsage("g", jan(2026)); u.Total != 6 {
322			t.Fatalf("jan usage changed after reopen = %d, want 6", u.Total)
